<template>
  <section class="signal-page">
    <div class="signal-toolbar">
      <div class="segmented"><button :class="{active: tab === 'desk'}" @click="tab='desk'">信号台</button><button :class="{active: tab === 'replay'}" @click="tab='replay'">规则回放</button><button :class="{active: tab === 'review'}" @click="tab='review'">信号复盘</button><button :class="{active: tab === 'alerts'}" @click="tab='alerts'">网页预警 <span v-if="desk?.alert_summary?.active" class="alert-count">{{ desk.alert_summary.active }}</span></button></div>
      <label>查看日期 <input v-model="day" type="date" @change="refresh" /></label>
      <button class="secondary" :disabled="store.signalDeskBusy" @click="refresh">刷新</button>
    </div>
    <div v-if="store.signalDeskError" class="service-alert">{{ store.signalDeskError }}</div>
    <div v-if="desk?.health?.status === 'NOT_DEPLOYED'" class="empty-card"><h3>信号服务尚未部署</h3><p>页面已经就绪，但服务器还没有运行实时 15 分钟扫描服务。部署后这里会显示真实信号，不会填充演示数据。</p></div>
    <template v-if="desk">
      <section class="operations-card">
        <div class="operations-head"><div><h3>信号服务</h3><p>{{ desk.operations?.service?.running ? '扫描正常运行' : desk.operations?.service?.enabled ? '已启用，但行情或扫描已超过 30 分钟' : '当前已停用' }}</p></div><button :class="desk.operations?.service?.enabled ? 'danger' : ''" @click="toggleService">{{ desk.operations?.service?.enabled ? '停用服务' : '启用服务' }}</button></div>
        <div class="operations-grid">
          <div><span>行情</span><b>{{ desk.operations?.service?.market_data_fresh ? '新鲜' : '过期/未扫描' }}</b><small>最近扫描 {{ time(desk.operations?.service?.last_scan_at_ms) }}</small></div>
          <div><span>手机推送</span><b>{{ desk.operations?.pushover?.configured ? (desk.operations?.pushover?.enabled ? '已启用' : '已配置但关闭') : '未配置' }}</b><small>今日 {{ desk.operations?.pushover?.today_sent || 0 }} / {{ desk.operations?.pushover?.daily_limit || 3 }} · 突破门槛 {{ Number(desk.operations?.parameters?.push_thresholds?.BREAKOUT_MOMENTUM || 0).toFixed(2) }}</small></div>
          <div><span>成交对照账户</span><b>{{ desk.operations?.binding?.account_id || '未绑定（不影响信号）' }}</b><small>只能使用与 TB4 物理隔离的子账户</small></div>
          <div><span>当前规则</span><b>15 分钟 · 每日最多 {{ desk.operations?.parameters?.candidate_limit || 30 }} 条</b><small>{{ desk.operations?.parameters?.liquidity_lookback_complete_utc_days || 30 }} 日成交额中位数 ≥ {{ money(desk.operations?.parameters?.liquidity_threshold_usdt) }}</small></div>
        </div>
        <div class="family-controls"><div v-for="family in families" :key="family.id"><span><b>{{ family.name }}</b><small>{{ family.note }}</small><em v-if="family.disabledReason">停用原因：{{ family.disabledReason }}</em></span><button :class="family.enabled ? 'danger' : ''" @click="toggleFamily(family)">{{ family.enabled ? '停用' : '启用' }}</button></div></div>
        <p class="honesty-note">这些规则调整了哪些机会会被提醒，不代表已经证明更赚钱。全部信号仍进入只追加模拟记录，由未来真实时间检验。</p>
        <details class="configuration-panel" open><summary>信号参数配置</summary><form @submit.prevent="saveConfiguration"><section v-for="group in configurationGroups" :key="group.name"><h4>{{ group.name }}</h4><div class="configuration-grid"><label v-for="field in group.fields" :key="field.key"><span>{{ field.label }}</span><small>{{ field.help }}</small><select v-if="field.kind === 'choice'" v-model="configurationDraft[field.key]"><option v-for="choice in field.choices" :key="choice" :value="choice">{{ cycleLabel(choice) }}</option></select><input v-else v-model="configurationDraft[field.key]" type="number" :min="field.minimum" :max="field.maximum" :step="field.kind === 'int' ? 1 : 'any'" required /><em>允许范围：{{ rangeLabel(field) }} · 当前生效：{{ displayValue(field) }}</em></label></div></section><label class="configuration-note"><span>变更备注（可选）</span><input v-model="configurationNote" maxlength="200" placeholder="例如：观察两周后降低放量门槛" /></label><div class="configuration-actions"><span>保存后立即生效，并写入不可覆盖的变更记录。</span><div><button type="button" class="secondary" :disabled="store.signalReplayBusy" @click="runReplay(true)">不保存，预览改动</button><button :disabled="configurationSaving">{{ configurationSaving ? '保存中…' : '保存参数' }}</button></div></div></form></details>
        <details><summary>可选成交对照账户</summary><div class="settings-row"><select v-model="bindingAccount"><option value="">不绑定账户</option><option v-for="account in exchangeAccounts" :key="account.id" :value="account.id">{{ account.account_label || account.id }} · {{ account.id }}</option></select><button @click="saveBinding">保存成交对照账户</button><span class="muted">手机推送凭证统一在“账户”页面配置。</span></div></details>
      </section>
      <div class="signal-answer"><strong>{{ answer }}</strong><span>每个信号都会自动进入模拟账；每日 30 条是工作量保护，不代表被截断的更差。</span></div>
      <div class="signal-kpis">
        <div><span>今日信号</span><strong>{{ desk.summary.signal_count }}</strong><small>{{ desk.summary.undecided_count }} 个待决定</small></div>
        <div><span>我做了 / 放弃</span><strong>{{ desk.summary.taken_count }} / {{ desk.summary.skipped_count }}</strong><small>决定写入不可覆盖账本</small></div>
        <div><span>模拟结果</span><strong :class="rClass(desk.summary.realized_r_total)">{{ r(desk.summary.realized_r_total) }}</strong><small>{{ desk.summary.closed_count }} 笔已结束</small></div>
        <div><span>扫描状态</span><strong>{{ healthLabel }}</strong><small>{{ latestScan }}</small></div>
      </div>

      <template v-if="tab === 'replay'">
        <section class="replay-panel"><div class="replay-toolbar"><div><h3>规则回放与改动预览</h3><p>查看规则在历史数据里会给出什么，不用于寻找最赚钱的参数。</p></div><select v-model.number="replayDays"><option :value="7">过去 7 天</option><option :value="30">过去 30 天</option></select><button :disabled="store.signalReplayBusy" @click="runReplay(false)">{{ store.signalReplayBusy ? '回放中…' : '按当前设置回放' }}</button></div><p class="replay-discipline">历史回放不预测未来。规则变更的真实效果，由信号模拟账在未来数据上裁决。</p><div v-if="store.signalReplayError" class="service-alert">{{ store.signalReplayError }}</div><div v-if="replay?.baseline?.data_gap" class="empty-card"><h3>历史数据不足</h3><p>{{ replay.baseline.data_gap }}</p><small>系统没有缩短时间段，也没有用不完整数据生成结果。</small></div><template v-else-if="replay?.baseline?.status === 'READY'"><div class="replay-comparison"><div><span>当前设置</span><strong>{{ replay.baseline.summary.total }}</strong><small>{{ familySummary(replay.baseline.summary) }}</small></div><div v-if="replay.preview"><span>改后预览</span><strong>{{ replay.preview.summary.total }}</strong><small>{{ familySummary(replay.preview.summary) }}</small></div><div><span>每日限额外</span><strong>{{ (replay.preview || replay.baseline).summary.truncated }}</strong><small>仍完整显示，不隐藏</small></div></div><div v-if="replay.comparison" class="replay-diff"><article><h4>新增 {{ replay.comparison.added.length }} 条</h4><p>{{ compactSignals(replay.comparison.added) }}</p></article><article><h4>消失 {{ replay.comparison.removed.length }} 条</h4><p>{{ compactSignals(replay.comparison.removed) }}</p></article><article><h4>币种构成变化</h4><p>{{ symbolChange(replay.comparison) }}</p></article></div><div class="replay-signal-list"><article v-for="signal in replaySignalsShown" :key="signal.signal_id" class="signal-card"><header><div><strong>{{ signal.symbol }}</strong><span class="direction long">做多</span><span class="muted">{{ reason(signal) }} · {{ time(signal.signal_time_ms) }}</span></div><span class="scope">{{ signal.candidate_scope === 'TRUNCATED' ? '每日限额外' : familyName(signal.family_id) }}</span></header><SignalCandleChart :symbol="signal.symbol" :before="signal.chart_before || []" :after="signal.chart_after || []" :entry="Number(signal.reference_entry_price)" :stop="Number(signal.suggested_stop_price)" /><div class="signal-levels"><span>参考进场 <b>{{ price(signal.reference_entry_price) }}</b></span><span>止损 <b>{{ price(signal.suggested_stop_price) }}</b></span><span>1R <b>{{ target(signal,1) }}</b></span><span>2R <b>{{ target(signal,2) }}</b></span><span>3R <b>{{ target(signal,3) }}</b></span><span>最大浮盈 <b>{{ replayR(signal.outcome?.maximum_favorable_r) }}</b></span><span>最大浮亏 <b>{{ replayR(signal.outcome?.maximum_adverse_r) }}</b></span><span>机械结果 <b>{{ replayR(signal.outcome?.mechanical_r) }}</b></span></div></article><div v-if="!replaySignalsShown.length" class="empty-card">这段时间没有产生信号。这也是有效的回放结果。</div></div></template></section>
      </template>

      <template v-else-if="tab === 'desk'">
        <div class="desk-layout">
          <main class="signal-list">
            <article v-for="signal in desk.signals" :id="`signal-${signal.signal_id}`" :key="signal.signal_id" :class="['signal-card', { 'deep-linked': deepLinkedSignalId === signal.signal_id }]">
              <header><div><strong>{{ signal.symbol }}</strong><span :class="['direction', signal.direction.toLowerCase()]">{{ signal.direction === 'LONG' ? '做多' : '做空' }}</span><span class="muted">{{ reason(signal) }} · {{ time(signal.signal_time_ms) }}</span></div><span class="scope">{{ scopeLabel(signal.candidate_scope) }}</span></header>
              <SignalCandleChart :symbol="signal.symbol" :before="signal.chart_before || []" :after="signal.simulation?.chart_after || []" :btc="signal.btc_context || []" :entry="Number(signal.simulation?.entry_price || signal.reference_entry_price)" :stop="Number(signal.simulation?.stop_price || signal.suggested_stop_price)" />
              <div class="signal-levels"><span>参考进场 <b>{{ price(signal.reference_entry_price) }}</b></span><span>止损 <b>{{ price(signal.suggested_stop_price) }}</b></span><span>1R <b>{{ target(signal, 1) }}</b></span><span>2R <b>{{ target(signal, 2) }}</b></span><span>3R <b>{{ target(signal, 3) }}</b></span><span>趋势强度 <b>{{ Number(signal.trend_strength_96).toFixed(2) }} · 同族第 {{ signal.trend_strength_rank }}/{{ signal.trend_strength_rank_total }}</b></span><span>手机 <b>{{ signal.push?.event_type === 'PUSH_SUCCEEDED' ? '已推送' : '仅列表' }}</b></span><span>有效期 <b>{{ expiryLabel(signal) }}</b></span><span>模拟 <b :class="rClass(signal.simulation?.realized_r)">{{ simulationLabel(signal.simulation) }}</b></span></div>
              <div v-if="signal.decision" class="decision-done">{{ signal.decision.decision === 'TAKEN' ? '已登记：我做了；真实成交会在账户同步后自动配对' : `已放弃${signal.decision.reason ? ` · ${signal.decision.reason}` : ''}` }}<span v-if="signal.manual_execution"> · 实际 {{ r(signal.manual_execution.realized_r) }}</span></div>
              <div v-else-if="signal.candidate_scope === 'INCLUDED'" class="decision-actions"><button :disabled="Boolean(signal.action_block) || signal.expired" :title="signal.expired ? '信号已过期，不能补标记' : signal.action_block?.reason === 'COOLDOWN_AFTER_STOP' ? `同向止损冷静期至 ${time(signal.action_block.until_ms)}` : signal.action_block ? '当日连续亏损/亏损限额熔断中' : ''" @click="openTaken(signal)">我做了</button><button class="secondary" @click="openSkipped(signal)">放弃</button><span v-if="signal.expired" class="negative">已过期</span><span v-else-if="signal.action_block?.reason === 'COOLDOWN_AFTER_STOP'" class="negative">冷静至 {{ time(signal.action_block.until_ms) }}</span><span v-else-if="signal.action_block" class="negative">当日熔断</span></div>
              <div v-else class="decision-done">仅保留模拟记录，不占用人工处理名额</div>
            </article>
            <div v-if="!desk.signals.length" class="empty-card">这一天没有信号。服务正常时，“没有信号”也是有效结果。</div>
          </main>
          <aside class="discipline-card"><h3>今日纪律</h3><dl><div><dt>止损随单</dt><dd>强制</dd></div><div><dt>亏损加仓</dt><dd>禁止</dd></div><div><dt>止损后冷却</dt><dd>同向 4 小时</dd></div><div><dt>计划外交易</dt><dd>不允许登记</dd></div></dl><p v-if="desk.discipline.cooldown_symbols?.length">冷却中：{{ desk.discipline.cooldown_symbols.join('、') }}</p><p class="muted">当前页面只登记与系统信号对应的一次完整交易；不会下单，也不读取账户金额。</p></aside>
        </div>
      </template>

      <template v-else-if="tab === 'review'">
        <div class="three-books">
          <div v-for="(book, key) in desk.review" :key="key"><span>{{ bookLabel(key) }}</span><strong :class="rClass(book.realized_r_total)">{{ r(book.realized_r_total) }}</strong><small>{{ book.closed_count }}/{{ book.count }} 笔已有结果 · {{ book.wins }} 盈 {{ book.losses }} 亏</small></div>
        </div>
        <section class="review-section"><h3>我做了的</h3><SignalReviewRow v-for="s in takenSignals" :key="s.signal_id" :signal="s" /></section>
        <section class="review-section"><h3>我没做的</h3><SignalReviewRow v-for="s in skippedSignals" :key="s.signal_id" :signal="s" /></section>
        <div v-if="!takenSignals.length && !skippedSignals.length" class="empty-card">这一天还没有人工决定。先在“信号台”登记做了或放弃，复盘才会形成。</div>
      </template>

      <template v-else>
        <div class="alert-kpis">
          <div><span>当前预警</span><strong>{{ desk.alert_summary?.active || 0 }}</strong><small>需要关注或仍在生效</small></div>
          <div><span>严重</span><strong class="negative">{{ desk.alert_summary?.critical || 0 }}</strong><small>账户冲突或纪律熔断</small></div>
          <div><span>错误</span><strong class="negative">{{ desk.alert_summary?.error || 0 }}</strong><small>扫描、行情或推送故障</small></div>
          <div><span>提醒</span><strong>{{ desk.alert_summary?.warning || 0 }}</strong><small>配置、冷静期和计划外交易</small></div>
        </div>
        <section class="web-alerts">
          <article v-for="alert in desk.alerts || []" :key="alert.alert_id" :class="['web-alert', `severity-${alert.severity.toLowerCase()}`, { recovered: alert.status === 'RECOVERED' }]">
            <div class="alert-icon">{{ alert.severity === 'CRITICAL' ? '!' : alert.severity === 'ERROR' ? '×' : 'i' }}</div>
            <div><header><strong>{{ alert.title }}</strong><span>{{ alert.category }} · {{ alert.status === 'RECOVERED' ? '已恢复' : '处理中' }}</span></header><p>{{ alert.message }}</p><small>{{ time(alert.recorded_at_ms) }}<template v-if="alert.until_ms"> · 解禁 {{ time(alert.until_ms) }}</template></small></div>
          </article>
          <div v-if="!desk.alerts?.length" class="empty-card"><h3>当前没有网页预警</h3><p>扫描、行情、推送、账户和纪律状态均未发现异常。</p></div>
        </section>
      </template>
    </template>

    <div v-if="dialog" class="signal-modal" @click.self="dialog=null"><form @submit.prevent="submitDialog"><h3>登记：放弃</h3><p>{{ dialog.signal.symbol }} · {{ dialog.signal.direction === 'LONG' ? '做多' : '做空' }}</p><label>放弃原因<select v-model="form.reason"><option>没盯盘</option><option>形态不喜欢</option><option>环境不好</option><option>其他</option></select></label><div><button type="button" class="secondary" @click="dialog=null">取消</button><button type="submit">确认并写入账本</button></div></form></div>
  </section>
</template>

<script setup>
import { computed, defineComponent, h, nextTick, onMounted, onUnmounted, reactive, ref, watch } from "vue";
import SignalCandleChart from "../components/SignalCandleChart.vue";
import { bindSignalAccount, controlSignalFamily, controlSignalService, decideSignal, loadSignalDesk, replaySignals, store, updateSignalConfiguration } from "../stores/appStore.js";
const tab=ref("desk"); const day=ref(new Date().toISOString().slice(0,10)); const dialog=ref(null); const form=reactive({reason:"没盯盘"}); const bindingAccount=ref(""); let timer=null;
const desk=computed(()=>store.signalDesk); const takenSignals=computed(()=>desk.value?.signals?.filter(s=>s.decision?.decision==="TAKEN")||[]); const skippedSignals=computed(()=>desk.value?.signals?.filter(s=>s.decision?.decision==="SKIPPED")||[]);
const exchangeAccounts=computed(()=>store.state?.exchange_accounts||[]);
const configurationDraft=reactive({});const configurationNote=ref("");const configurationSaving=ref(false);
const replayDays=ref(7);const replay=computed(()=>store.signalReplay);const replaySignalsShown=computed(()=>replay.value?.preview?.signals||replay.value?.baseline?.signals||[]);
const configurationFields=computed(()=>desk.value?.operations?.configuration?.fields||[]);const configurationGroups=computed(()=>[...new Set(configurationFields.value.map(row=>row.group))].map(name=>({name,fields:configurationFields.value.filter(row=>row.group===name)})));
watch(configurationFields,fields=>{for(const field of fields)if(configurationDraft[field.key]===undefined)configurationDraft[field.key]=field.value},{immediate:true});
const familyDefinitions=[{id:"BREAKOUT_MOMENTUM",name:"突破信号",note:"向上突破且成交活跃"},{id:"OVERSOLD_REBOUND",name:"高位回调",note:"只看上升趋势里从高位发生的急跌"},{id:"SUSTAINED_STRENGTH",name:"持续强势",note:"价格和成交持续走强"}];
const families=computed(()=>familyDefinitions.map(row=>{const state=desk.value?.operations?.family_controls?.[row.id]||{};return{...row,enabled:state.enabled!==false,disabledReason:state.disabled_reason||""}}));
const deepLinkedSignalId=location.hash.startsWith("#signals/")?decodeURIComponent(location.hash.slice("#signals/".length)):"";
const answer=computed(()=>!desk.value?.summary?.signal_count?"今天暂时没有信号":`今天 ${desk.value.summary.signal_count} 个信号，${desk.value.summary.undecided_count} 个还没决定`);
const healthLabel=computed(()=>({RUNNING:"运行正常",WAITING_FIRST_SCAN:"等待首次扫描",LEDGER_ERROR:"账本异常"}[desk.value?.health?.status]||desk.value?.health?.status)); const latestScan=computed(()=>desk.value?.health?.latest_scan?`最近扫描 ${time(desk.value.health.latest_scan.signal_close_time_ms)}`:"尚无扫描记录");
function refresh(){return loadSignalDesk(day.value)} function time(ms){return ms?new Date(Number(ms)).toLocaleString("zh-CN",{hour12:false}):"—"} function price(v){return Number(v).toLocaleString("en-US",{maximumSignificantDigits:9})} function money(v){return `${Number(v||0).toLocaleString("zh-CN")} USDT`} function r(v){if(v===null||v===undefined)return "待结束";const n=Number(v);return `${n>=0?"+":""}${n.toFixed(2)}R`} function rClass(v){return Number(v)>0?"positive":Number(v)<0?"negative":""}
function cycleLabel(value){return {UP:"上升",RANGE:"震荡",DOWN:"下降"}[value]||value}function rangeLabel(field){return field.kind==='choice'?field.choices.map(cycleLabel).join('、'):`${field.minimum} ～ ${field.maximum}`}function displayValue(field){return field.kind==='choice'?cycleLabel(field.value):field.value}
function familyName(value){return {BREAKOUT_MOMENTUM:'突破信号',OVERSOLD_REBOUND:'高位回调',SUSTAINED_STRENGTH:'持续强势'}[value]||'信号'}function replayR(value){if(value===null||value===undefined)return '数据不足';return `${Number(value)>=0?'+':''}${Number(value).toFixed(2)}R`}function familySummary(summary){const rows=summary?.by_family||{};return `突破 ${rows.BREAKOUT_MOMENTUM||0} · 高位回调 ${rows.OVERSOLD_REBOUND||0} · 持续强势 ${rows.SUSTAINED_STRENGTH||0}`}function compactSignals(rows){return rows?.length?rows.slice(0,12).map(row=>`${row.symbol} ${familyName(row.family_id)}`).join('、')+(rows.length>12?'…':''):'无'}function symbolChange(comparison){const before=comparison.before?.by_symbol||{};const after=comparison.after?.by_symbol||{};const changed=[...new Set([...Object.keys(before),...Object.keys(after)])].filter(key=>(before[key]||0)!==(after[key]||0));return changed.length?changed.slice(0,16).map(key=>`${key} ${before[key]||0}→${after[key]||0}`).join('、'):'没有变化'}
function expiryLabel(signal){const left=Number(signal.expires_at_ms)-Date.now();if(left<=0)return "已过期";return `剩余 ${Math.ceil(left/60000)} 分钟（至 ${time(signal.expires_at_ms)}）`}
function target(s,n){const sign=s.direction==="LONG"?1:-1;return price(Number(s.reference_entry_price)+sign*n*Number(s.initial_risk_price))} function reason(s){if(s.family_id==="BREAKOUT_MOMENTUM")return `向上突破 · 放量 ${Number(s.reason?.relative_quote_volume||0).toFixed(1)} 倍`;if(s.family_id==="SUSTAINED_STRENGTH")return `持续强势 · 量能比 ${Number(s.reason?.volume_ratio_3d_10d||0).toFixed(2)}`;return `${Number(s.reason?.drop_fraction||0)*100>=0?"下跌":""}${(Number(s.reason?.drop_fraction||0)*100).toFixed(1)}% 后企稳`} function scopeLabel(v){return {INCLUDED:"候选范围内",TRUNCATED:"超过每日 30 条",PENDING_SCOPE:"等待当日排序"}[v]||v} function simulationLabel(s){return s?.status==="CLOSED"?r(s.realized_r):s?.status==="OPEN"?"持有中":"等待进场"} function bookLabel(k){return {all_signal_simulation:"全部信号模拟账",chosen_signal_simulation:"我选择的模拟账",actual_manual:"我的实际成交账"}[k]||k}
async function openTaken(s){await decideSignal({signal_id:s.signal_id,decision:"TAKEN",entry_price:Number(s.reference_entry_price),stop_price:Number(s.suggested_stop_price),reason:null})} function openSkipped(s){dialog.value={kind:"skip",signal:s};form.reason="没盯盘"}
async function submitDialog(){const d=dialog.value;if(!d)return;const ok=await decideSignal({signal_id:d.signal.signal_id,decision:"SKIPPED",reason:form.reason,entry_price:null,stop_price:null});if(ok)dialog.value=null}
async function toggleService(){await controlSignalService(!desk.value?.operations?.service?.enabled)} async function saveBinding(){await bindSignalAccount(bindingAccount.value)}
async function toggleFamily(family){let why=null;if(family.enabled){why=prompt(`请填写停用“${family.name}”的原因：`);if(!why?.trim())return}await controlSignalFamily(family.id,!family.enabled,why);await refresh()}
async function saveConfiguration(){const values={};for(const field of configurationFields.value){const raw=configurationDraft[field.key];const value=field.kind==='choice'?raw:Number(raw);if(value!==field.value)values[field.key]=value}configurationSaving.value=true;try{const saved=await updateSignalConfiguration(values,configurationNote.value);if(saved){configurationNote.value="";for(const field of saved.operations?.configuration?.fields||[])configurationDraft[field.key]=field.value}}finally{configurationSaving.value=false}}
function changedConfiguration(){const values={};for(const field of configurationFields.value){const value=field.kind==='choice'?configurationDraft[field.key]:Number(configurationDraft[field.key]);if(value!==field.value)values[field.key]=value}return values}async function runReplay(preview){tab.value='replay';await replaySignals(replayDays.value,preview?changedConfiguration():null)}
const SignalReviewRow=defineComponent({props:{signal:Object},setup(p){return()=>h("article",{class:"review-row"},[h("div",{class:"review-head"},[h("strong",p.signal.symbol),h("span",p.signal.direction==="LONG"?"做多":"做空"),h("b",{class:rClass(p.signal.manual_execution?.realized_r??p.signal.simulation?.realized_r)},p.signal.decision?.decision==="TAKEN"?(p.signal.manual_execution?`实际 ${r(p.signal.manual_execution.realized_r)}`:"实际成交待同步"):`若机械执行 ${r(p.signal.simulation?.realized_r)}`)]),h(SignalCandleChart,{symbol:p.signal.symbol,before:p.signal.chart_before||[],after:p.signal.simulation?.chart_after||[],btc:p.signal.btc_context||[],entry:Number(p.signal.simulation?.entry_price||p.signal.reference_entry_price),stop:Number(p.signal.simulation?.stop_price||p.signal.suggested_stop_price)}),h("p",{class:"muted"},p.signal.decision?.decision==="TAKEN"?`机械结果 ${r(p.signal.simulation?.realized_r)}；实际结果 ${r(p.signal.manual_execution?.realized_r)}`:`放弃原因：${p.signal.decision?.reason||"未填写"}`)])}});
onMounted(async()=>{await refresh();bindingAccount.value=desk.value?.operations?.binding?.account_id||"";if(deepLinkedSignalId){await nextTick();document.getElementById(`signal-${deepLinkedSignalId}`)?.scrollIntoView({behavior:"smooth",block:"center"})}timer=setInterval(refresh,15000)});onUnmounted(()=>clearInterval(timer));
</script>

